#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "W/m²".parse::<IrradianceUnit>(),
        Ok(IrradianceUnit::WattPerSquareMeter)
    );
    assert_eq!(
        format!("2.5 {}", "W/m²").parse::<Irradiance>(),
        Ok(Irradiance::new(2.5, IrradianceUnit::WattPerSquareMeter))
    );
    assert_eq!(
        "pW/m²".parse::<IrradianceUnit>(),
        Ok(IrradianceUnit::PicowattPerSquareMeter)
    );
    assert_eq!(
        format!("2.5 {}", "pW/m²").parse::<Irradiance>(),
        Ok(Irradiance::new(2.5, IrradianceUnit::PicowattPerSquareMeter))
    );
    assert_eq!(
        "nW/m²".parse::<IrradianceUnit>(),
        Ok(IrradianceUnit::NanowattPerSquareMeter)
    );
    assert_eq!(
        format!("2.5 {}", "nW/m²").parse::<Irradiance>(),
        Ok(Irradiance::new(2.5, IrradianceUnit::NanowattPerSquareMeter))
    );
    assert_eq!(
        "µW/m²".parse::<IrradianceUnit>(),
        Ok(IrradianceUnit::MicrowattPerSquareMeter)
    );
    assert_eq!(
        format!("2.5 {}", "µW/m²").parse::<Irradiance>(),
        Ok(Irradiance::new(
            2.5,
            IrradianceUnit::MicrowattPerSquareMeter
        ))
    );
    assert_eq!(
        "mW/m²".parse::<IrradianceUnit>(),
        Ok(IrradianceUnit::MilliwattPerSquareMeter)
    );
    assert_eq!(
        format!("2.5 {}", "mW/m²").parse::<Irradiance>(),
        Ok(Irradiance::new(
            2.5,
            IrradianceUnit::MilliwattPerSquareMeter
        ))
    );
    assert_eq!(
        "kW/m²".parse::<IrradianceUnit>(),
        Ok(IrradianceUnit::KilowattPerSquareMeter)
    );
    assert_eq!(
        format!("2.5 {}", "kW/m²").parse::<Irradiance>(),
        Ok(Irradiance::new(2.5, IrradianceUnit::KilowattPerSquareMeter))
    );
    assert_eq!(
        "MW/m²".parse::<IrradianceUnit>(),
        Ok(IrradianceUnit::MegawattPerSquareMeter)
    );
    assert_eq!(
        format!("2.5 {}", "MW/m²").parse::<Irradiance>(),
        Ok(Irradiance::new(2.5, IrradianceUnit::MegawattPerSquareMeter))
    );
    assert_eq!(
        "W/cm²".parse::<IrradianceUnit>(),
        Ok(IrradianceUnit::WattPerSquareCentimeter)
    );
    assert_eq!(
        format!("2.5 {}", "W/cm²").parse::<Irradiance>(),
        Ok(Irradiance::new(
            2.5,
            IrradianceUnit::WattPerSquareCentimeter
        ))
    );
    assert_eq!(
        "pW/cm²".parse::<IrradianceUnit>(),
        Ok(IrradianceUnit::PicowattPerSquareCentimeter)
    );
    assert_eq!(
        format!("2.5 {}", "pW/cm²").parse::<Irradiance>(),
        Ok(Irradiance::new(
            2.5,
            IrradianceUnit::PicowattPerSquareCentimeter
        ))
    );
    assert_eq!(
        "nW/cm²".parse::<IrradianceUnit>(),
        Ok(IrradianceUnit::NanowattPerSquareCentimeter)
    );
    assert_eq!(
        format!("2.5 {}", "nW/cm²").parse::<Irradiance>(),
        Ok(Irradiance::new(
            2.5,
            IrradianceUnit::NanowattPerSquareCentimeter
        ))
    );
    assert_eq!(
        "µW/cm²".parse::<IrradianceUnit>(),
        Ok(IrradianceUnit::MicrowattPerSquareCentimeter)
    );
    assert_eq!(
        format!("2.5 {}", "µW/cm²").parse::<Irradiance>(),
        Ok(Irradiance::new(
            2.5,
            IrradianceUnit::MicrowattPerSquareCentimeter
        ))
    );
    assert_eq!(
        "mW/cm²".parse::<IrradianceUnit>(),
        Ok(IrradianceUnit::MilliwattPerSquareCentimeter)
    );
    assert_eq!(
        format!("2.5 {}", "mW/cm²").parse::<Irradiance>(),
        Ok(Irradiance::new(
            2.5,
            IrradianceUnit::MilliwattPerSquareCentimeter
        ))
    );
    assert_eq!(
        "kW/cm²".parse::<IrradianceUnit>(),
        Ok(IrradianceUnit::KilowattPerSquareCentimeter)
    );
    assert_eq!(
        format!("2.5 {}", "kW/cm²").parse::<Irradiance>(),
        Ok(Irradiance::new(
            2.5,
            IrradianceUnit::KilowattPerSquareCentimeter
        ))
    );
    assert_eq!(
        "MW/cm²".parse::<IrradianceUnit>(),
        Ok(IrradianceUnit::MegawattPerSquareCentimeter)
    );
    assert_eq!(
        format!("2.5 {}", "MW/cm²").parse::<Irradiance>(),
        Ok(Irradiance::new(
            2.5,
            IrradianceUnit::MegawattPerSquareCentimeter
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<Irradiance>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = Irradiance::from_base(6.0);
    let b = Irradiance::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = Irradiance::<i64>::from_base(7);
    let b = Irradiance::<i64>::from_base(2);
    assert_eq!(a + b, Irradiance::from_base(9));
    assert_eq!(a % b, Irradiance::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<Irradiance<i64>>(),
        Irradiance::from_base(9)
    );
}
